// Passo 1: duas fichas escritas à mão — a estrutura é repetida.
const ana = { nome: 'Ana', idade: 18 };
const bia = { nome: 'Bia', idade: 20 };

// Passo 2: o comportamento vive FORA dos objetos.
function apresentar(pessoa) {
  // Se o objeto não tiver nome ou idade, a frase quebra — sem aviso.
  return `${pessoa.nome} tem ${pessoa.idade} anos.`;
}

// Passo 3: funciona, mas com risco: nada garante a estrutura.
console.log(apresentar(ana)); // imprime: Ana tem 18 anos.
console.log(apresentar(bia)); // imprime: Bia tem 20 anos.

// Passo 4: e se alguém passar um objeto sem nome?
console.log(apresentar({ idade: 30 })); // imprime: undefined tem 30 anos.
